<script setup lang="ts">import {ref,computed,onMounted,onUnmounted} from 'vue';import {useRoute} from 'vue-router';import {runs} from '../stores/runs';import {reviews} from '../stores/reviews';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import StatusPill from '../components/common/StatusPill.vue';import Notice from '../components/common/Notice.vue';import EmptyState from '../components/common/EmptyState.vue';import RunSelector from '../components/RunSelector.vue';import PhaseTable from '../components/PhaseTable.vue';import TailBars from '../components/TailBars.vue';import {minutes} from '../utils/format';const route=useRoute(),selected=ref(String(route.query.run||'demo-run')),action=ref('优先复核阶段交接和异常票号；结合线路工况后制定改进动作。'),notice=ref('');const {error,busy,act}=useTask();let timer:ReturnType<typeof setInterval>;onMounted(()=>{runs.load();timer=setInterval(runs.load,2000)});onUnmounted(()=>clearInterval(timer));const run=computed(()=>runs.items.value.find(r=>r.id===selected.value)),result=computed(()=>run.value?.result);function submit(){act(async()=>{await reviews.create({run_id:selected.value,action:action.value});notice.value='已提交复核，请管理员到归档页处理。'})}</script><template><PageHeading eyebrow="RUN LOG / 04" title="看见阶段，也看见不确定。" note="总时延按每票阶段之和计算；重采样尾延迟归因为描述性比较，不直接代表因果。"/><div class="result-toolbar"><RunSelector v-model="selected" :rows="runs.items.value"/><StatusPill v-if="run" :status="run.status"/></div>
<div v-if="run?.result?.dataset_version!==undefined" class="version-note">
 本运行口径钉住数据版本 <b>v{{run.result.dataset_version}}</b><template v-if="run.result.current_dataset_version>run.result.dataset_version">；批次之后已补报到 <b>v{{run.result.current_dataset_version}}</b>，本运行保留原口径，新建运行才使用更新数据。</template><template v-else>，与当前批次一致。</template>
</div><Notice :message="error||runs.error.value"/><Notice v-if="run?.status==='failed'" :message="run.error"/><EmptyState v-if="run && ['queued','running'].includes(run.status)" text="后台worker正在计算，可保持此页等待。结果每两秒刷新。"/><div v-if="run?.status==='completed' && result" class="results-grid"><section><div class="result-summary"><div><small>有效样本</small><strong>{{result.valid_count}} 票</strong></div><div><small>总时延 P95</small><strong>{{minutes(result.total_quantiles.p95)}}</strong></div><div><small>隔离样本</small><strong>{{result.rejected_count}} 票</strong></div></div><h2>阶段分位表</h2><PhaseTable :rows="result.phases"/><h2>质量隔离原因</h2><div class="table-wrap"><table><thead><tr><th>票号</th><th>隔离原因</th></tr></thead><tbody><tr v-for="r in result.rejected.slice(0,12)" :key="r.shipment_id"><td>{{r.shipment_id}}</td><td>{{r.reason}}</td></tr></tbody></table></div><form v-if="canWrite()" class="review-form" @submit.prevent="submit"><label>提交行动复核<textarea v-model="action" required minlength="8" rows="3"></textarea></label><button :disabled="busy">提交复核</button><p class="success" v-if="notice">{{notice}}</p></form></section><aside class="field-note"><p class="eyebrow">TAIL ATTRIBUTION</p><h2>把长尾逐段摊开</h2><TailBars :rows="result.tail.contributions"/><p>真实观测尾分位 {{minutes(result.tail.observed_tail)}}<br>独立重采样尾分位 {{minutes(result.tail.modeled_tail)}}</p><p class="footnote">{{result.tail.assumption}} 重采样{{result.tail.replicates}}次，seed={{result.tail.seed}}。</p></aside></div></template>
